177	    /**
178	     * The owner's numeric membership level, derived on read from the fields assigned at create.
179	     * It starts at 1, gains 1 when an email is present, gains 1 when {@code namesakeCount} is 0,
180	     * and is capped at 3 (level 4 is reserved for tenure).
181	     *
182	     * @return the membership level, from 1 to 3
183	     */
184	    @Transient
185	    public Integer getMembershipLevel() {
186	        int level = 1;
187	        if (this.email != null && !this.email.isBlank()) {
188	            level++;
189	        }
190	        if (this.namesakeCount != null && this.namesakeCount == 0) {
191	            level++;
192	        }
193	        return Math.min(level, 3);
194	    }
