207	    /**
208	     * The owner's check digit, derived on read: a single Luhn check digit computed over the
209	     * digits contained in the owner's {@code customerCode}.
210	     *
211	     * @return the Luhn check digit (0-9), or {@code null} when no customer code is assigned
212	     */
213	    @Transient
214	    public Integer getCheckDigit() {
215	        if (this.customerCode == null) {
216	            return null;
217	        }
218	        int sum = 0;
219	        boolean dbl = true;
220	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
221	            char c = this.customerCode.charAt(i);
222	            if (c < '0' || c > '9') {
223	                continue;
224	            }
225	            int d = c - '0';
226	            if (dbl) {
227	                d *= 2;
228	                if (d > 9) {
229	                    d -= 9;
230	                }
231	            }
232	            sum += d;
233	            dbl = !dbl;
234	        }
235	        return (10 - (sum % 10)) % 10;
236	    }
