270	        return Collections.unmodifiableList(sortedPets);
271	    }
272	
273	    public void setPets(List<Pet> pets) {
274	        this.pets = new HashSet<>(pets);
275	    }
276	
277	    public void addPet(Pet pet) {
278	        getPetsInternal().add(pet);
279	        pet.setOwner(this);
280	    }
281	
282	    /**
283	     * Return the Pet with the given name, or null if none found for this Owner.
284	     *
285	     * @param name to test
286	     * @return true if pet name is already in use
287	     */
288	    public Pet getPet(String name) {
289	        return getPet(name, false);
290	    }
291	
292	    /**
293	     * Return the Pet with the given name, or null if none found for this Owner.
294	     *
295	     * @param name to test
296	     * @return true if pet name is already in use
297	     */
298	    public Pet getPet(String name, boolean ignoreNew) {
299	        name = name.toLowerCase();
300	        for (Pet pet : getPetsInternal()) {
301	            if (!ignoreNew || !pet.isNew()) {
302	                String compName = pet.getName();
303	                compName = compName.toLowerCase();
304	                if (compName.equals(name)) {
305	                    return pet;
306	                }
307	            }
308	        }
309	        return null;
310	    }
311	
312	    public Pet getPet(Integer petId) {
313	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
314	    }
315	
