310	    /**
311	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
312	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
313	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
314	     */
315	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
316	        "NSW", new int[] {2000, 2099},
317	        "VIC", new int[] {3000, 3099},
318	        "QLD", new int[] {4000, 4099});
319	
320	    /**
321	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
322	     * {@code null} value is accepted. When present it has already been constrained to four digits
323	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
324	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
325	     * the postcode must fall within that region's inclusive range
326	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
327	     *
328	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
329	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
330	     *                                  city's region
331	     */
332	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
333	        String postcode = ownerFieldsDto.getPostcode();
334	        if (postcode == null) {
335	            return;
336	        }
337	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
338	            .regionFor(ownerFieldsDto.getCity());
339	        int[] range = REGION_POSTCODE_RANGE.get(region);
340	        if (range == null) {
341	            return;
342	        }
343	        int value = Integer.parseInt(postcode);
344	        if (value < range[0] || value > range[1]) {
345	            throw new InvalidPostcodeException(postcode);
346	        }
347	    }
