479	    /**
480	     * Assigns the owner's {@code customerCode} on create, formatted
481	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
482	     * (preferring the postcode range, falling back to the city — the same derivation that yields
483	     * the owner's {@code locality}, see
484	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
485	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
486	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
487	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
488	     * customer code only when their normalized telephone and last name both match.
489	     *
490	     * @param owner the owner being created (with its {@code postcode}, {@code city},
491	     *              {@code telephone} and {@code lastName} already set)
492	     */
493	    private void assignCustomerCode(Owner owner) {
494	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
495	            .regionFor(owner.getPostcode(), owner.getCity());
496	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
497	            .substring(0, 8).toUpperCase(Locale.ROOT);
498	        owner.setCustomerCode(region + "-" + hash8);
499	    }
