501	    /**
502	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
503	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
504	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
505	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
506	     * canonicalized fields, every owner in the same household — including one joining an existing
507	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
508	     * order.
509	     *
510	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
511	     */
512	    private void assignHouseholdId(Owner owner) {
513	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
514	    }
