516	    /**
517	     * Derives the stable {@code householdId} for the given {@code lastName} and {@code address}:
518	     * {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the SHA-256
519	     * digest of the collapsed {@code lastName} and {@code address} (see {@link #collapse}) joined
520	     * by a {@code '\n'}. Because it is derived purely from those two canonicalized fields, every
521	     * owner in the same household receives the same value, independent of create order. Shared by
522	     * {@link #assignHouseholdId} (which persists it) and {@link #identityKeyFor} (which folds it
523	     * into the identity key for duplicate detection).
524	     *
525	     * @param lastName the owner's last name
526	     * @param address  the owner's address
527	     * @return the derived household id
528	     */
529	    private static String householdIdFor(String lastName, String address) {
530	        String key = collapse(lastName) + "\n" + collapse(address);
531	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
532	    }
