534	    /**
535	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
536	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
537	     * after this create. Because {@code householdId} is derived from the owner's collapsed
538	     * {@code lastName} and {@code address} (see {@link #assignHouseholdId}), the count reflects every
539	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
540	     * The count is taken before this owner is persisted, so it is one more than the number of
541	     * existing household members.
542	     *
543	     * @param owner the owner being created (with its {@code householdId} already assigned)
544	     */
545	    private void assignHouseholdMemberCount(Owner owner) {
546	        String householdId = owner.getHouseholdId();
547	        long existing = this.clinicService.findAllOwners().stream()
548	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
549	            .count();
550	        owner.setHouseholdMemberCount((int) (existing + 1));
551	    }
