553	    /**
554	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
555	     * already share this owner's {@code firstName} and {@code lastName}, compared
556	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
557	     * pre-existing namesakes.
558	     *
559	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
560	     */
561	    private void assignNamesakeCount(Owner owner) {
562	        String firstName = owner.getFirstName();
563	        String lastName = owner.getLastName();
564	        long count = this.clinicService.findAllOwners().stream()
565	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
566	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
567	            .count();
568	        owner.setNamesakeCount((int) count);
569	    }
