601	     */
602	    private void assignBulkSignupWarning(Owner owner) {
603	        LocalDate registrationDate = owner.getRegistrationDate();
604	        long count = this.clinicService.findAllOwners().stream()
605	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
606	            .count();
607	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
