610	    /**
611	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
612	     *
613	     * @param value the string to hash
614	     * @return the 64-character lower-case hex digest
615	     */
616	    private static String sha256Hex(String value) {
617	        try {
618	            byte[] digest = MessageDigest.getInstance("SHA-256")
619	                .digest(value.getBytes(StandardCharsets.UTF_8));
620	            StringBuilder sb = new StringBuilder(digest.length * 2);
621	            for (byte b : digest) {
622	                sb.append(String.format("%02x", b));
623	            }
624	            return sb.toString();
625	        }
626	        catch (NoSuchAlgorithmException e) {
627	            throw new IllegalStateException("SHA-256 not available", e);
628	        }
629	    }
630	
631	    /**
632	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
633	     * owner. This single key consolidates what used to be three separate duplicate checks
634	     * (telephone, email and household): the key is
635	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
636	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
637	     * matches an existing owner's. Because the telephone is part of the key, two members of the
638	     * same household (same {@code householdId}) with different telephones have different identity
639	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
640	     * and email have already been normalized by {@link #normalizeTelephone} and
641	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
642	     * input formats collapse to the same value.
643	     *
644	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
645	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
646	     *                                    whole identity key
647	     */
648	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
649	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress(),
650	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
651	        boolean duplicate = this.clinicService.findAllOwners().stream()
652	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getAddress(),
653	                owner.getTelephone(), owner.getEmail()))
654	            .anyMatch(identityKey::equals);
655	        if (duplicate) {
656	            throw new DuplicateIdentityException(identityKey);
657	        }
658	    }
659	
660	    /**
661	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
662	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
663	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
664	     * absent), and the {@code householdId} is derived from the collapsed {@code lastName} and
665	     * {@code address} the same way {@link #assignHouseholdId} assigns it (see
666	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
667	     * their whole identities match, regardless of the exact input formats.
668	     *
669	     * @param lastName  the owner's last name
670	     * @param address   the owner's address
671	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
672	     * @param email     the owner's email, possibly {@code null}
673	     * @return the canonical identity key
674	     */
675	    private static String identityKeyFor(String lastName, String address, String telephone, String email) {
676	        String normalizedTelephone = toE164(telephone);
677	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
678	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
679	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, address);
680	    }
681	
682	    /**
683	     * The maximum number of owners permitted in a single city. A create is rejected once the
684	     * owner's city already contains this many owners.
685	     */
686	    private static final long CITY_CAPACITY = 50;
687	
688	    /**
689	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
690	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
691	     * before this owner is persisted.
692	     *
693	     * @param city the submitted city
694	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
695	     */
696	    private void rejectCityAtCapacity(String city) {
697	        long count = this.clinicService.findAllOwners().stream()
698	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
699	            .count();
700	        if (count >= CITY_CAPACITY) {
701	            throw new CityAtCapacityException(city);
702	        }
703	    }
704	
705	    /**
706	     * The maximum number of owners permitted to be created in a single day. A create is
707	     * rejected once this many owners already carry today's {@code registrationDate}.
708	     */
709	    private static final long DAILY_LIMIT = 100;
710	
711	    /**
712	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
713	     * business day as their {@code registrationDate}. The day counted against is this create's
714	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
715	     * so owners are counted per adjusted business day. The count is taken before this owner is
716	     * persisted.
717	     *
718	     * @param businessDay the effective, business-day-adjusted registration date of this create
719	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
720	     */
721	    private void rejectDailyLimit(LocalDate businessDay) {
722	        long count = this.clinicService.findAllOwners().stream()
723	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
724	            .count();
725	        if (count >= DAILY_LIMIT) {
726	            throw new DailyOwnerLimitExceededException(businessDay);
727	        }
728	    }
729	
730	    /**
731	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
732	     * every internal run of whitespace is collapsed to a single space, and the result is
733	     * lower-cased. A {@code null} value collapses to the empty string.
734	     *
735	     * @param value the value to canonicalize, possibly {@code null}
736	     * @return the collapsed, lower-cased value
737	     */
738	    private static String collapse(String value) {
739	        if (value == null) {
740	            return "";
741	        }
742	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
743	    }
744	
745	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
746	    @Override
747	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
748	        Owner owner = this.clinicService.findOwnerById(ownerId);
749	        if (owner != null) {
750	            Pet pet = owner.getPet(petId);
751	            if (pet != null) {
752	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
753	            }
754	        }
755	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
756	    }
757	}
