17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.controller.CityAtCapacityException;
33	import org.springframework.samples.petclinic.rest.controller.DailyOwnerLimitExceededException;
34	import org.springframework.samples.petclinic.rest.controller.DuplicateEmailException;
35	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
36	import org.springframework.samples.petclinic.rest.controller.DuplicateIdentityException;
37	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
38	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
39	import org.springframework.samples.petclinic.rest.controller.InvalidPostcodeException;
40	import org.springframework.samples.petclinic.rest.controller.RequiredFieldsMissingException;
41	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
42	import org.springframework.security.access.AccessDeniedException;
43	import org.springframework.validation.BindingResult;
44	import org.springframework.validation.FieldError;
45	import org.springframework.web.bind.MethodArgumentNotValidException;
46	import org.springframework.web.bind.annotation.ControllerAdvice;
47	import org.springframework.web.bind.annotation.ExceptionHandler;
48	import org.springframework.web.bind.annotation.ResponseBody;
49	
50	/**
51	 * Global Exception handler for REST controllers.
52	 * <p>
53	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
54	 *
55	 * @author Vitaliy Fedoriv
56	 * @author Alexander Dudkin
57	 */
58	@ControllerAdvice
59	public class ExceptionControllerAdvice {
60	
61	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
62	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
63	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
64	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
65	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
66	    private static final String ERROR_DUPLICATE_EMAIL = "An owner with the given email already exists";
67	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given last name and address already exists";
68	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity already exists";
69	    private static final String ERROR_INVALID_EMAIL = "The request contains an invalid email address";
70	    private static final String ERROR_INVALID_POSTCODE = "The request contains a postcode that is not valid for the owner's city";
71	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
72	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners for today has already been reached";
73	
74	    /**
75	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
76	     * class.
77	     *
78	     * @param e     Object referring to the thrown exception.
79	     * @param status HTTP response status.
80	     * @param url URL request.
81	     */
82	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
83	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
84	        problemDetail.setType(URI.create(url.toString()));
85	        problemDetail.setTitle(e.getClass().getSimpleName());
86	        problemDetail.setDetail(detail);
87	        problemDetail.setProperty("timestamp", Instant.now());
88	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
89	        return problemDetail;
90	    }
91	
92	    /**
93	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
94	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
95	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
96	     * would catch it and report an authorization failure as a 500.
97	     *
98	     * @param e The {@link AccessDeniedException} to propagate
99	     * @throws AccessDeniedException always
100	     */
101	    @ExceptionHandler(AccessDeniedException.class)
102	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
103	        throw e;
104	    }
105	
106	    /**
107	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
108	     *
109	     * @param e The {@link Exception} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
112	     */
113	    @ExceptionHandler(Exception.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
116	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
117	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
118	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
119	        return ResponseEntity.status(status).body(detail);
120	    }
121	
122	    /**
123	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
124	     * method returns a 404 Not Found status if an entity does not exist.
125	     *
126	     * @param e The {@link DataIntegrityViolationException} to be handled
127	     * @param request {@link HttpServletRequest} object referring to the current request.
128	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
129	     */
130	    @ExceptionHandler(DataIntegrityViolationException.class)
131	    @ResponseBody
132	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
133	        logger.warn("Data integrity violation at {} {}: {}",
134	            request.getMethod(),
135	            request.getRequestURI(),
136	            e.getMessage());
137	        logger.debug("Data integrity violation stacktrace", e);
138	        HttpStatus status = HttpStatus.NOT_FOUND;
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
140	        return ResponseEntity.status(status).body(detail);
141	    }
142	
143	    /**
144	     * Handles exception thrown by Bean Validation on controller methods parameters
145	     *
146	     * @param e The {@link MethodArgumentNotValidException} to be handled
147	     * @param request {@link HttpServletRequest} object referring to the current request.
148	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
149	     */
150	    @ExceptionHandler(MethodArgumentNotValidException.class)
151	    @ResponseBody
152	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
153	        HttpStatus status = HttpStatus.BAD_REQUEST;
154	        BindingErrorsResponse errors = new BindingErrorsResponse();
155	        BindingResult bindingResult = e.getBindingResult();
156	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
157	        List<String> invalidFields = bindingResult.getFieldErrors().stream()
158	            .map(FieldError::getField)
159	            .distinct()
160	            .toList();
161	        detail.setProperty("errors", invalidFields);
162	        if (bindingResult.hasErrors()) {
163	            errors.addAllErrors(bindingResult);
164	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
165	                .map(fieldError -> {
166	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
167	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
168	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
169	                        fieldError.getField(),
170	                        defaultMessage,
171	                        rejectedValue);
172	                    return new ValidationMessageDto(message)
173	                        .putAdditionalProperty("field", fieldError.getField())
174	                        .putAdditionalProperty("rejectedValue", rejectedValue)
175	                        .putAdditionalProperty("defaultMessage", defaultMessage);
176	                })
177	                .toList();
178	            logger.debug("Validation error at {} {}: {}",
179	                request.getMethod(),
180	                request.getRequestURI(),
181	                bindingResult.getFieldErrors());
182	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
183	            return ResponseEntity.status(status).body(detail);
184	        }
185	        return ResponseEntity.status(status).body(detail);
186	    }
187	
188	    /**
189	     * Handles {@link RequiredFieldsMissingException} raised when a request omits or blanks
190	     * out mandatory fields. Returns a 400 Bad Request whose body carries an {@code errors}
191	     * array listing the name of each offending field.
192	     *
193	     * @param e The {@link RequiredFieldsMissingException} to be handled
194	     * @param request {@link HttpServletRequest} object referring to the current request.
195	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
196	     */
197	    @ExceptionHandler(RequiredFieldsMissingException.class)
198	    @ResponseBody
199	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
200	        HttpStatus status = HttpStatus.BAD_REQUEST;
201	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
202	        detail.setProperty("errors", e.getFields());
203	        logger.debug("Missing required fields at {} {}: {}",
204	            request.getMethod(),
205	            request.getRequestURI(),
206	            e.getFields());
207	        return ResponseEntity.status(status).body(detail);
208	    }
209	
210	    /**
211	     * Handles {@link DuplicateTelephoneException} raised when a create request supplies a
212	     * normalized telephone already used by another owner. Returns a 409 Conflict whose body
213	     * carries an {@code errors} array naming the {@code telephone} field.
214	     *
215	     * @param e The {@link DuplicateTelephoneException} to be handled
216	     * @param request {@link HttpServletRequest} object referring to the current request.
217	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
218	     */
219	    /**
220	     * Handles {@link InvalidEmailException} raised when a create or update request supplies an
221	     * {@code email} that is present but not a syntactically valid address. Returns a 400 Bad
222	     * Request whose body carries an {@code errors} array naming the {@code email} field.
223	     *
224	     * @param e The {@link InvalidEmailException} to be handled
225	     * @param request {@link HttpServletRequest} object referring to the current request.
226	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
227	     */
228	    @ExceptionHandler(InvalidEmailException.class)
229	    @ResponseBody
230	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
231	        HttpStatus status = HttpStatus.BAD_REQUEST;
232	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_EMAIL);
233	        detail.setProperty("errors", List.of("email"));
234	        logger.debug("Invalid email at {} {}: {}",
235	            request.getMethod(),
236	            request.getRequestURI(),
237	            e.getEmail());
238	        return ResponseEntity.status(status).body(detail);
239	    }
240	
241	    /**
242	     * Handles {@link InvalidPostcodeException} raised when a create request supplies a
243	     * {@code postcode} that is present but out of range for the owner's city's region. Returns a
244	     * 400 Bad Request whose body carries an {@code errors} array naming the {@code postcode} field.
245	     *
246	     * @param e The {@link InvalidPostcodeException} to be handled
247	     * @param request {@link HttpServletRequest} object referring to the current request.
248	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
249	     */
250	    @ExceptionHandler(InvalidPostcodeException.class)
251	    @ResponseBody
252	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
253	        HttpStatus status = HttpStatus.BAD_REQUEST;
254	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_POSTCODE);
255	        detail.setProperty("errors", List.of("postcode"));
256	        logger.debug("Invalid postcode at {} {}: {}",
