284	
285	    /**
286	     * Handles {@link DuplicateIdentityException} raised when a create request supplies an owner
287	     * whose whole derived {@code identityKey} already equals that of an existing owner. This one
288	     * key consolidates the former telephone, email and household duplicate checks. Returns a 409
289	     * Conflict whose body carries an {@code errors} array naming the {@code identityKey} field.
290	     *
291	     * @param e The {@link DuplicateIdentityException} to be handled
292	     * @param request {@link HttpServletRequest} object referring to the current request.
293	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
294	     */
295	    @ExceptionHandler(DuplicateIdentityException.class)
296	    @ResponseBody
297	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
298	        HttpStatus status = HttpStatus.CONFLICT;
299	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
300	        detail.setProperty("errors", List.of("identityKey"));
301	        logger.debug("Duplicate identity at {} {}: {}",
302	            request.getMethod(),
303	            request.getRequestURI(),
304	            e.getIdentityKey());
305	        return ResponseEntity.status(status).body(detail);
306	    }
307	
308	    @ExceptionHandler(DuplicateTelephoneException.class)
309	    @ResponseBody
310	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
311	        HttpStatus status = HttpStatus.CONFLICT;
