17	package org.springframework.samples.petclinic.rest.controller;
18	
19	/**
20	 * Raised when a create request supplies a {@code postcode} that is present but not valid for
21	 * the owner's city: it falls outside the inclusive 4-digit range fixed for the city's region
22	 * (Sydney/NSW 2000-2099, Melbourne/VIC 3000-3099, Brisbane/QLD 4000-4099). Carries the
23	 * rejected value so the exception handler can report a 400 Bad Request naming the
24	 * {@code postcode} field. A city with no known region imposes no range and never raises this.
25	 */
26	public class InvalidPostcodeException extends RuntimeException {
27	
28	    private final String postcode;
29	
30	    public InvalidPostcodeException(String postcode) {
31	        super("Invalid postcode for city: " + postcode);
32	        this.postcode = postcode;
33	    }
34	
35	    public String getPostcode() {
36	        return this.postcode;
37	    }
38	}
